# Triton implementation of linalg_pinv (Moore-Penrose pseudoinverse).
# Two Triton paths, both based on one-sided Jacobi SVD:
#   * small matrices (m, n <= 32): a single fused kernel keeps the whole matrix
#     in registers and unrolls the sweeps statically.
#   * larger matrices: the matrix stays in global memory and each Jacobi round
#     rotates n/2 disjoint column pairs in parallel, so nothing is unrolled and
#     register pressure stays bounded.
import linecache
import logging

import torch
import triton
import triton.language as tl

import flag_gems
from flag_gems import runtime
from flag_gems.utils import libentry

logger = logging.getLogger(__name__)

# Largest dimension handled by the fused register-resident kernel. Above this the
# statically unrolled sweeps blow up compile time and the matrix no longer fits
# in registers, so the blocked global-memory path takes over.
#
# On the Kunlunxin XPU backend the fused kernel does not compile at all
# ("out of resource: uni_sram" plus an illegal `tt.reduce` from the axis=1
# reductions), so the threshold is 0 there and every shape uses the blocked
# path. The fused kernel below is kept for the backends that can compile it.
_FUSED_MAX_DIM = 0 if runtime.device.vendor_name == "kunlunxin" else 32

# Cyclic one-sided Jacobi converges in well under 10 sweeps for practical inputs;
# the blocked path uses a fixed count to avoid a device-to-host sync per sweep.
_BLOCKED_NUM_SWEEPS = 10

# ---------------------------------------------------------------------------
# Fast path for small square matrices (the shapes the benchmark exercises).
#
# The generic fused kernel rotates one column pair at a time and extracts each
# column from a [BLOCK_M, BLOCK_N] register tile with a masked tl.sum, so every
# pair pays several full-tile reduction trees and the sweep is a chain of
# n*(n-1)/2 * sweeps serial steps. This path instead keeps the working matrix
# in a small global scratch laid out transposed (one column of B = one row of
# W) and rotates all disjoint pairs of a round-robin round in parallel as
# [P, BLOCK_W] gather/scatter tiles, so a whole sweep costs (n-1) rounds
# instead of n*(n-1)/2 pair steps. The rotation angle uses the flattened
# dlaev2 form, which needs only two axis=1 reduction trees per round
# (gamma and beta-alpha fused into one tree).
#
# Correctness guards copied from the gcu400 linalg_cond / linalg_svd
# experience: num_warps is pinned to 1 (wider warp counts miscompile wide
# vector rotations on this backend), and the kernel contains no masked memory
# operations at all - every load address is clamped or statically in bounds
# and inactive lanes are zeroed with register-level tl.where (masked
# load/store around 2D outer-product accumulation miscompiles on this
# backend). The 2D outer-product accumulator is only used on power-of-two
# shapes with fully unmasked loads/stores.
# Sweep counts for the fast path. Cyclic one-sided Jacobi converges
# quadratically; on the well-conditioned inputs of the accuracy gate the
# result is bit-stable from 5 sweeps on (18-matrix spectrum scan: random
# well-conditioned, cond 1e4/1e6, clustered, near-threshold and rank-deficient
# all match the previous 10/8-sweep output to <1e-6 at 6 sweeps), so 6 sweeps
# carries two spare sweeps over the convergence knee.
_FAST_SQUARE_DIMS = (4, 8)
_FAST_SWEEPS = {4: 6, 8: 6}
_PAIR_TABLE_CACHE = {}

# The external triton_gcu converter pipeline occasionally dies with a
# host-level SIGSEGV in one of its shell helpers on fresh compiles; a failed
# compile is not cached, so re-invoking the launch retries it (see
# compiler_issues/flaggems_kthvalue_toolchain_flaky_segv.md).
_TOOLCHAIN_FLAKE_MARKERS = (
    "Segmentation fault",
    "converterResult",
    "serializing the module",
    "core dumped",
)
_TOOLCHAIN_FLAKE_ATTEMPTS = 3


def _launch_with_toolchain_retry(launch):
    for attempt in range(_TOOLCHAIN_FLAKE_ATTEMPTS):
        try:
            return launch()
        except Exception as err:
            msg = str(err)
            if attempt < _TOOLCHAIN_FLAKE_ATTEMPTS - 1 and any(
                marker in msg for marker in _TOOLCHAIN_FLAKE_MARKERS
            ):
                logger.warning(
                    "toolchain flake during kernel launch (attempt %d), retrying: %s",
                    attempt + 1,
                    msg.splitlines()[0][:200],
                )
                continue
            raise


def _pinv_pair_table(n, sweeps, device):
    """Round-robin (circle method) pairing schedule as a [TOTAL, 2, P] int32 tensor.

    Same formula as the generic svd cyclic Jacobi kernel: player 0 is fixed
    while the remaining `ring` players rotate, so every round yields P = n/2
    disjoint pairs and `ring` rounds cover all n*(n-1)/2 pairs exactly once.
    The table is pure schedule metadata (independent of the input values) and
    is cached per (n, sweeps, device).
    """
    key = (n, sweeps, str(device))
    table = _PAIR_TABLE_CACHE.get(key)
    if table is not None:
        return table
    round_size = n if n % 2 == 0 else n + 1
    ring = round_size - 1
    n_pairs = round_size // 2
    rounds = []
    for _sweep in range(sweeps):
        for step in range(round_size - 1):
            ps, qs = [], []
            for pair in range(n_pairs):
                pos_p = pair
                pos_q = round_size - 1 - pair
                p = 0 if pos_p == 0 else ((pos_p + ring - step - 1) % ring) + 1
                q = 0 if pos_q == 0 else ((pos_q + ring - step - 1) % ring) + 1
                ps.append(p)
                qs.append(q)
            rounds.append((ps, qs))
    table = torch.tensor(rounds, dtype=torch.int32, device=device)
    _PAIR_TABLE_CACHE[key] = table
    return table


@libentry()
@triton.jit
def _pinv_fast_kernel(
    A_ptr,
    W_ptr,
    OUT_ptr,
    PAIRS_ptr,
    atol_val,
    rtol_val,
    TOTAL,
    N: tl.constexpr,
    BLOCK_W: tl.constexpr,
    P: tl.constexpr,
):
    """Single-launch pair-vectorized one-sided Jacobi pseudoinverse.

    Scratch W is [N, BLOCK_W] per batch element: columns [0, N) hold B^T (the
    working matrix, one column of B per row of W) and columns [N, 2N) hold V^T
    (the accumulated right rotations). A column rotation of (B, V) is a row
    rotation of both halves at once, so one gather/scatter pair per round
    rotates the fused row. After convergence sigma_j = ||W[j, :N]|| and
    pinv[i, l] = sum_j V[i, j] * B[l, j] / sigma_j^2.
    """
    batch_idx = tl.program_id(0)
    w_base = W_ptr + batch_idx * N * BLOCK_W
    a_base = A_ptr + batch_idx * N * N
    out_base = OUT_ptr + batch_idx * N * N

    rows = tl.arange(0, N)
    wcols = tl.arange(0, BLOCK_W)

    # Prologue: W[j, c] = A[c, j] for c < N, identity in the V half. The A
    # load clamps the column index so every address is in bounds; the padded
    # lanes are discarded by the register-level where (no masked load).
    a_cols = tl.minimum(wcols, N - 1)
    a_t = tl.load(a_base + a_cols[None, :] * N + rows[:, None])
    w_init = tl.where(
        wcols[None, :] < N,
        a_t,
        tl.where(wcols[None, :] == rows[:, None] + N, 1.0, 0.0),
    )
    tl.store(w_base + rows[:, None] * BLOCK_W + wcols[None, :], w_init)

    # Jacobi rounds. Every (p, q) pair index is < N by construction, so the
    # gathers and scatters are unmasked.
    lane = tl.arange(0, P)
    b_half = wcols[None, :] < N
    for t in tl.range(0, TOTAL):
        idx_p = tl.load(PAIRS_ptr + t * (2 * P) + lane)
        idx_q = tl.load(PAIRS_ptr + t * (2 * P) + P + lane)
        gp = tl.load(w_base + idx_p[:, None] * BLOCK_W + wcols[None, :])
        gq = tl.load(w_base + idx_q[:, None] * BLOCK_W + wcols[None, :])
        bp = tl.where(b_half, gp, 0.0)
        bq = tl.where(b_half, gq, 0.0)
        # Two axis=1 trees: gamma and (beta - alpha) fused into one tree.
        gam = tl.sum(bp * bq, axis=1)
        dif = tl.sum(bq * bq - bp * bp, axis=1)
        # Flattened dlaev2 rotation; gamma == 0 gives t == 0 (no rotation)
        # except the all-zero corner, which the zero-denominator guard maps
        # to t == 0 as well.
        rt = tl.sqrt(dif * dif + 4.0 * gam * gam)
        denom = dif + tl.where(dif >= 0.0, rt, -rt)
        denom = tl.where(denom == 0.0, 1.0, denom)
        t_val = 2.0 * gam / denom
        c = tl.rsqrt(1.0 + t_val * t_val)
        s = t_val * c
        newp = c[:, None] * gp - s[:, None] * gq
        newq = s[:, None] * gp + c[:, None] * gq
        tl.store(w_base + idx_p[:, None] * BLOCK_W + wcols[None, :], newp)
        tl.store(w_base + idx_q[:, None] * BLOCK_W + wcols[None, :], newq)

    # Finalize: singular values from the B half, threshold, scale the V half
    # by 1/sigma^2 (zeroed below cutoff), then contract pinv as a sum of N
    # outer products of W rows. All loads/stores unmasked (N is a power of
    # two and every index is inside the scratch).
    X = tl.load(w_base + rows[:, None] * BLOCK_W + wcols[None, :])
    bpart = tl.where(b_half, X, 0.0)
    sig = tl.sqrt(tl.sum(bpart * bpart, axis=1))
    sig_max = tl.max(sig, axis=0)
    thr = tl.maximum(atol_val, sig_max * rtol_val)
    invsq = tl.where(sig > thr, 1.0 / (sig * sig + 1e-38), 0.0)
    X2 = tl.where(wcols[None, :] >= N, X * invsq[:, None], X)
    tl.store(w_base + rows[:, None] * BLOCK_W + wcols[None, :], X2)
    acc = tl.zeros((N, N), dtype=tl.float32)
    for j in tl.static_range(0, N):
        b_j = tl.load(w_base + j * BLOCK_W + rows)
        v_j = tl.load(w_base + j * BLOCK_W + N + rows)
        acc += v_j[:, None] * b_j[None, :]
    tl.store(out_base + rows[:, None] * N + rows[None, :], acc)


def _fast_square_pinv(A_flat, batch, n, atol_val, rtol_val):
    """Pseudoinverse of a (batch, n, n) float32 stack in one kernel launch."""
    sweeps = _FAST_SWEEPS[n]
    block_w = 2 * n
    n_pairs = n // 2
    total = sweeps * (n - 1)
    device = A_flat.device
    W = torch.empty((batch, n, block_w), dtype=torch.float32, device=device)
    out = torch.empty((batch, n, n), dtype=torch.float32, device=device)
    pairs = _pinv_pair_table(n, sweeps, device)

    def launch():
        _pinv_fast_kernel[(batch,)](
            A_flat,
            W,
            out,
            pairs,
            atol_val,
            rtol_val,
            total,
            N=n,
            BLOCK_W=block_w,
            P=n_pairs,
            num_warps=1,
        )

    _launch_with_toolchain_retry(launch)
    return out


@libentry()
@triton.jit
def _jacobi_pinv_kernel(
    A_ptr,
    OUT_ptr,
    m: tl.constexpr,
    n: tl.constexpr,
    k: tl.constexpr,
    a_batch_stride,
    out_batch_stride,
    atol_val,
    rtol_val,
    NUM_SWEEPS: tl.constexpr,
    BLOCK_M: tl.constexpr,
    BLOCK_N: tl.constexpr,
    BLOCK_K: tl.constexpr,
):
    """
    Fused Jacobi SVD + pseudoinverse kernel.
    Each program handles one batch element.
    k = min(m, n).

    Algorithm (one-sided Jacobi on columns of A):
      1. Load A (m x n) into W
      2. Initialize V = I_n
      3. For each sweep, for column pairs (p, q):
         - Compute alpha = W[:,p]^T W[:,p], beta = W[:,q]^T W[:,q], gamma = W[:,p]^T W[:,q]
         - Compute Jacobi rotation (c, s) to zero gamma
         - Rotate columns p, q of W and V
      4. After convergence: sigma_j = ||W[:,j]||, U[:,j] = W[:,j]/sigma_j
      5. pinv = V @ diag(1/S_filt) @ U^T
    """
    batch_idx = tl.program_id(0)

    a_offset = batch_idx * a_batch_stride
    out_offset = batch_idx * out_batch_stride

    # Load A into W [BLOCK_M, BLOCK_N]
    rows = tl.arange(0, BLOCK_M)
    cols = tl.arange(0, BLOCK_N)

    # Load full matrix
    W = tl.load(
        A_ptr + a_offset + rows[:, None] * n + cols[None, :],
        mask=(rows[:, None] < m) & (cols[None, :] < n),
        other=0.0,
    )

    # V = I_n [BLOCK_N, BLOCK_N]
    vcols = tl.arange(0, BLOCK_N)
    vrows = tl.arange(0, BLOCK_N)
    V = tl.where(vrows[:, None] == vcols[None, :], 1.0, 0.0).to(tl.float32)

    # Jacobi sweeps
    for _sweep in tl.static_range(0, NUM_SWEEPS):
        for p in tl.static_range(0, BLOCK_N):
            for q in tl.static_range(0, BLOCK_N):
                if q > p:
                    if p < n and q < n:
                        # Extract columns p and q from in-register W
                        # Use the in-register W
                        # Use the in-register W
                        # W[:, p] where col == p
                        mask_p = cols[None, :] == p
                        mask_q = cols[None, :] == q

                        # Extract columns via reduction
                        w_p = tl.sum(tl.where(mask_p, W, 0.0), axis=1)  # [BLOCK_M]
                        w_q = tl.sum(tl.where(mask_q, W, 0.0), axis=1)  # [BLOCK_M]

                        # Gram elements
                        alpha = tl.sum(w_p * w_p, axis=0)
                        beta = tl.sum(w_q * w_q, axis=0)
                        gamma = tl.sum(w_p * w_q, axis=0)

                        # Skip if off-diagonal is tiny
                        scale = tl.maximum(alpha, beta) + 1e-30
                        should_rotate = tl.abs(gamma) > 1e-10 * scale

                        # Jacobi rotation: zero the off-diagonal
                        diff = beta - alpha
                        tau = diff / (2.0 * gamma + 1e-30)
                        sign_tau = tl.where(tau >= 0.0, 1.0, -1.0)
                        t = sign_tau / (tl.abs(tau) + tl.sqrt(tau * tau + 1.0))
                        c = 1.0 / tl.sqrt(1.0 + t * t)
                        s = t * c

                        c = tl.where(should_rotate, c, 1.0)
                        s = tl.where(should_rotate, s, 0.0)

                        # Rotate W: W[:, p] = c*w_p - s*w_q, W[:, q] = s*w_p + c*w_q
                        new_wp = c * w_p - s * w_q
                        new_wq = s * w_p + c * w_q

                        W = tl.where(mask_p, new_wp[:, None], W)
                        W = tl.where(mask_q, new_wq[:, None], W)

                        # Rotate V: V[:, p], V[:, q]
                        vmask_p = vcols[None, :] == p
                        vmask_q = vcols[None, :] == q
                        v_p = tl.sum(tl.where(vmask_p, V, 0.0), axis=1)  # [BLOCK_N]
                        v_q = tl.sum(tl.where(vmask_q, V, 0.0), axis=1)  # [BLOCK_N]
                        new_vp = c * v_p - s * v_q
                        new_vq = s * v_p + c * v_q
                        V = tl.where(vmask_p, new_vp[:, None], V)
                        V = tl.where(vmask_q, new_vq[:, None], V)

    # Compute singular values and pseudoinverse
    # sigma_j = ||W[:, j]||, U[:, j] = W[:, j] / sigma_j
    # pinv[i, j] = sum_l V[i, l] * (1/sigma_l) * U[j, l]  (where sigma_l > thr)

    # First find sigma_max for threshold
    sigma_max = tl.zeros([1], dtype=tl.float32)
    for j in tl.static_range(0, BLOCK_N):
        if j < n:
            mask_j = cols[None, :] == j
            w_j = tl.sum(tl.where(mask_j, W, 0.0), axis=1)
            sj = tl.sqrt(tl.sum(w_j * w_j, axis=0))
            sigma_max = tl.maximum(sigma_max, sj)

    thr = tl.maximum(atol_val, sigma_max * rtol_val)

    # Accumulate pinv = V @ diag(1/s_filt) @ U^T
    # pinv is (n x m)
    out_rows = tl.arange(0, BLOCK_N)  # n
    out_cols = tl.arange(0, BLOCK_M)  # m
    PINV = tl.zeros([BLOCK_N, BLOCK_M], dtype=tl.float32)

    for j in tl.static_range(0, BLOCK_N):
        if j < n:
            mask_j = cols[None, :] == j
            w_j = tl.sum(tl.where(mask_j, W, 0.0), axis=1)  # [BLOCK_M] = U_raw
            sj = tl.sqrt(tl.sum(w_j * w_j, axis=0))
            is_valid = sj > thr

            # pinv contribution = (1/sj) * v_j @ u_j^T
            # where u_j = w_j / sj, so (1/sj) * u_j = w_j / sj^2
            inv_sj_sq = tl.where(is_valid, 1.0 / (sj * sj + 1e-38), 0.0)

            # V[:, j]
            vmask_j = vcols[None, :] == j
            v_j = tl.sum(tl.where(vmask_j, V, 0.0), axis=1)  # [BLOCK_N]

            # Outer: v_j[:, None] * (w_j * inv_sj_sq)[None, :] -> [BLOCK_N, BLOCK_M]
            PINV += v_j[:, None] * (w_j * inv_sj_sq)[None, :]

    # Store output (n x m)
    tl.store(
        OUT_ptr + out_offset + out_rows[:, None] * m + out_cols[None, :],
        PINV,
        mask=(out_rows[:, None] < n) & (out_cols[None, :] < m),
    )


@libentry()
@triton.jit
def _eye_init_kernel(
    V_ptr,
    C,
    v_batch_stride,
    BLOCK: tl.constexpr,
):
    """Write the C x C identity matrix into the accumulated rotation buffer V."""
    batch_idx = tl.program_id(0)
    pid_r = tl.program_id(1)

    rows = pid_r * BLOCK + tl.arange(0, BLOCK)
    base = V_ptr + batch_idx * v_batch_stride

    for c0 in tl.range(0, C, BLOCK):
        cols = c0 + tl.arange(0, BLOCK)
        val = tl.where(rows[:, None] == cols[None, :], 1.0, 0.0)
        tl.store(
            base + rows[:, None] * C + cols[None, :],
            val,
            mask=(rows[:, None] < C) & (cols[None, :] < C),
        )


@libentry()
@triton.jit
def _jacobi_round_kernel(
    W_ptr,
    V_ptr,
    R: tl.constexpr,
    C: tl.constexpr,
    w_batch_stride,
    v_batch_stride,
    round_idx,
    ring,
    BLOCK_R: tl.constexpr,
    BLOCK_C: tl.constexpr,
):
    """One round of a parallel one-sided Jacobi sweep.

    Column pairs are formed with the circle method: the last player of an
    even-sized field is fixed while the remaining `ring` players rotate. Every
    round therefore yields disjoint pairs, so all pairs in a round can be
    rotated concurrently, and `ring` rounds cover all C*(C-1)/2 pairs exactly
    once.
    """
    batch_idx = tl.program_id(0)
    pair_idx = tl.program_id(1)

    # Circle-method pairing. `ring` == n_even - 1, the fixed player is `ring`.
    if pair_idx == 0:
        p = ring
        q = round_idx % ring
    else:
        p = (round_idx + pair_idx) % ring
        # round_idx - pair_idx >= -ring, so one +ring makes the modulo positive.
        q = (round_idx - pair_idx + ring) % ring

    if (p < C) & (q < C):
        w_base = W_ptr + batch_idx * w_batch_stride
        v_base = V_ptr + batch_idx * v_batch_stride

        # Gram elements of the column pair, reduced over all R rows.
        alpha = tl.zeros([], dtype=tl.float32)
        beta = tl.zeros([], dtype=tl.float32)
        gamma = tl.zeros([], dtype=tl.float32)
        for r0 in tl.range(0, R, BLOCK_R):
            rows = r0 + tl.arange(0, BLOCK_R)
            rmask = rows < R
            w_p = tl.load(w_base + rows * C + p, mask=rmask, other=0.0)
            w_q = tl.load(w_base + rows * C + q, mask=rmask, other=0.0)
            alpha += tl.sum(w_p * w_p)
            beta += tl.sum(w_q * w_q)
            gamma += tl.sum(w_p * w_q)

        # Jacobi rotation that zeroes the off-diagonal Gram entry.
        scale = tl.maximum(alpha, beta) + 1e-30
        should_rotate = tl.abs(gamma) > 1e-10 * scale
        diff = beta - alpha
        tau = diff / (2.0 * gamma + 1e-30)
        sign_tau = tl.where(tau >= 0.0, 1.0, -1.0)
        t = sign_tau / (tl.abs(tau) + tl.sqrt(tau * tau + 1.0))
        c = 1.0 / tl.sqrt(1.0 + t * t)
        s = t * c
        c = tl.where(should_rotate, c, 1.0)
        s = tl.where(should_rotate, s, 0.0)

        # Apply the rotation to columns p, q of W (R rows).
        for r0 in tl.range(0, R, BLOCK_R):
            rows = r0 + tl.arange(0, BLOCK_R)
            rmask = rows < R
            w_p = tl.load(w_base + rows * C + p, mask=rmask, other=0.0)
            w_q = tl.load(w_base + rows * C + q, mask=rmask, other=0.0)
            tl.store(w_base + rows * C + p, c * w_p - s * w_q, mask=rmask)
            tl.store(w_base + rows * C + q, s * w_p + c * w_q, mask=rmask)

        # Accumulate the same rotation into V (C rows).
        for r0 in tl.range(0, C, BLOCK_C):
            rows = r0 + tl.arange(0, BLOCK_C)
            rmask = rows < C
            v_p = tl.load(v_base + rows * C + p, mask=rmask, other=0.0)
            v_q = tl.load(v_base + rows * C + q, mask=rmask, other=0.0)
            tl.store(v_base + rows * C + p, c * v_p - s * v_q, mask=rmask)
            tl.store(v_base + rows * C + q, s * v_p + c * v_q, mask=rmask)


@libentry()
@triton.jit
def _column_norm_kernel(
    W_ptr,
    S_ptr,
    R: tl.constexpr,
    C,
    w_batch_stride,
    BLOCK_R: tl.constexpr,
):
    """Singular values: sigma_j = ||W[:, j]|| once the sweeps have converged."""
    batch_idx = tl.program_id(0)
    j = tl.program_id(1)

    if j < C:
        w_base = W_ptr + batch_idx * w_batch_stride
        acc = tl.zeros([], dtype=tl.float32)
        for r0 in tl.range(0, R, BLOCK_R):
            rows = r0 + tl.arange(0, BLOCK_R)
            rmask = rows < R
            w = tl.load(w_base + rows * C + j, mask=rmask, other=0.0)
            acc += tl.sum(w * w)
        tl.store(S_ptr + batch_idx * C + j, tl.sqrt(acc))


# ---------------------------------------------------------------------------
# Register-resident path (Kunlunxin XPU, small square matrices).
#
# The blocked path launches one kernel per Jacobi round (34 launches for a 4x4
# batch, 74 for 8x8) and a single launch costs ~33us on this backend, so small
# matrices are pure launch overhead. This path keeps the whole matrix in
# registers: one program per batch element, every column of W and V living in
# its own 1-D register vector, and every column pair of a sweep unrolled. Each
# reduction is then a 1-D tl.sum over a register vector - the backend rejects
# tl.reduce over axis 0 of a 2-D tile, which rules out keeping W as one tile -
# and the whole SVD comes out of one launch; the pinv contraction is a single
# native matmul, so the op is 2 launches instead of 34/74.
#
# Triton does not allow indexing a Python list of tensors by the loop variable
# and has no __setitem__, so the unrolled body is generated as source text per
# (C, R, sweeps) shape. The source is registered in linecache, which is what
# inspect.getsource (used by @triton.jit) reads from.
_REG_MAX_C = 8 if runtime.device.vendor_name == "kunlunxin" else 0
_REG_KERNELS = {}


def _reg_kernel_source(C, R, sweeps):
    BLOCK_R = triton.next_power_of_2(R)
    BLOCK_C = triton.next_power_of_2(C)
    lines = []

    def emit(line=""):
        lines.append(line)

    emit("import triton")
    emit("import triton.language as tl")
    emit("")
    emit("")
    emit("@triton.jit")
    emit("def _pinv_reg_kernel(A_ptr, W_ptr, V_ptr, atol_val, rtol_val):")
    emit("    pid = tl.program_id(0)")
    emit(f"    wbase = pid * {C * R}")
    emit(f"    vbase = pid * {C * C}")
    emit(f"    rs = tl.arange(0, {BLOCK_R})")
    emit(f"    rmask = rs < {R}")
    # W column j is A[:, j], i.e. wbase + r * C + j for row r.
    for j in range(C):
        emit(
            f"    w{j} = tl.load(A_ptr + wbase + rs * {C} + {j}, mask=rmask, other=0.0)"
        )
    emit(f"    vs = tl.arange(0, {BLOCK_C})")
    for j in range(C):
        emit(f"    v{j} = tl.where(vs == {j}, 1.0, 0.0)")
    # Sigma is refreshed at the end of every sweep instead of once after the
    # loop: on this backend a tl.sum over a value produced by a runtime
    # tl.range loop fails to compile ("scf.for ... iter_arg have different
    # type"), while a reduction *inside* the loop is fine. The scalars left in
    # the carried variables after the last sweep are the converged norms.
    for j in range(C):
        emit(f"    sig{j} = tl.zeros([], dtype=tl.float32)")

    # The sweep counter stays a runtime loop: the columns are plain variables,
    # so the loop body is just the unrolled pair list and the sweep count costs
    # nothing at compile time.
    emit(f"    for _sweep in tl.range(0, {sweeps}):")
    for p in range(C):
        for q in range(p + 1, C):
            emit(f"        alpha = tl.sum(w{p} * w{p})")
            emit(f"        beta = tl.sum(w{q} * w{q})")
            emit(f"        gamma = tl.sum(w{p} * w{q})")
            emit("        scale = tl.maximum(alpha, beta) + 1e-30")
            emit("        rot = tl.abs(gamma) > 1e-10 * scale")
            emit("        tau = (beta - alpha) / (2.0 * gamma + 1e-30)")
            emit("        sign_tau = tl.where(tau >= 0.0, 1.0, -1.0)")
            emit("        t = sign_tau / (tl.abs(tau) + tl.sqrt(tau * tau + 1.0))")
            emit("        c = 1.0 / tl.sqrt(1.0 + t * t)")
            emit("        s = t * c")
            emit("        c = tl.where(rot, c, 1.0)")
            emit("        s = tl.where(rot, s, 0.0)")
            for prefix in ("w", "v"):
                emit(f"        cur_p = {prefix}{p}")
                emit(f"        cur_q = {prefix}{q}")
                emit(f"        {prefix}{p} = c * cur_p - s * cur_q")
                emit(f"        {prefix}{q} = s * cur_p + c * cur_q")
    for j in range(C):
        emit(f"        sig{j} = tl.sqrt(tl.sum(w{j} * w{j}))")

    emit("    sigma_max = sig0")
    for j in range(1, C):
        emit(f"    sigma_max = tl.maximum(sigma_max, sig{j})")
    emit("    thr = tl.maximum(atol_val, sigma_max * rtol_val)")
    for j in range(C):
        emit(
            f"    inv{j} = tl.where(sig{j} > thr, 1.0 / (sig{j} * sig{j} + 1e-38), 0.0)"
        )
    # Nothing below builds a 2-D tile: on this backend a [C, R] tile blows the
    # uni_sram budget, and mixing 1-D and 2-D uses of the same value trips an
    # arith.mulf type error. So the kernel writes the rotated W and the
    # threshold-scaled V, and the contraction runs on the native matmul.
    for j in range(C):
        emit(f"    tl.store(W_ptr + wbase + rs * {C} + {j}, w{j}, mask=rmask)")
        emit(
            f"    tl.store(V_ptr + vbase + {j} * {C} + vs, v{j} * inv{j}, mask=vs < {C})"
        )
    return "\n".join(lines) + "\n"


def _reg_kernel(C, R):
    key = (C, R)
    kernel = _REG_KERNELS.get(key)
    if kernel is None:
        sweeps = 10 if C <= 4 else 8
        source = _reg_kernel_source(C, R, sweeps)
        name = f"<flag_gems_pinv_reg_{C}_{R}>"
        linecache.cache[name] = (len(source), None, source.splitlines(True), name)
        namespace = {}
        exec(compile(source, name, "exec"), namespace)
        kernel = namespace["_pinv_reg_kernel"]
        _REG_KERNELS[key] = kernel
    return kernel


def _reg_pinv(W: torch.Tensor, batch: int, R: int, C: int, atol_val, rtol_val):
    """Pseudoinverse of a (batch, R, C) stack: one register-resident launch plus matmul."""
    device = W.device
    W_rot = torch.empty(batch, R, C, dtype=torch.float32, device=device)
    V_scaled = torch.empty(batch, C, C, dtype=torch.float32, device=device)
    _reg_kernel(C, R)[(batch,)](W, W_rot, V_scaled, atol_val, rtol_val)
    # The kernel stores the j-th column of V as row j, so V_scaled holds
    # V^T diag(1/sigma) with 1/sigma folded in and the singular values below the
    # cutoff zeroed. pinv[i, l] = sum_j V[i, j] W[l, j] / sigma_j^2 is then
    # (W_rot @ V_scaled)^T, i.e. a contiguous matmul and a view transpose.
    return torch.matmul(W_rot, V_scaled).transpose(-2, -1)


def _blocked_pinv(W: torch.Tensor, batch: int, R: int, C: int, atol_val, rtol_val):
    """Pseudoinverse of a (batch, R, C) stack with R >= C, kept in global memory.

    W is rotated in place and must already be a private float32 copy.
    Returns the (batch, C, R) pseudoinverse.
    """
    device = W.device

    V = torch.empty(batch, C, C, dtype=torch.float32, device=device)

    # Row-block sizes for the streaming reductions; tuned only to keep a full
    # warp busy while bounding register use, and independent of the shape.
    BLOCK_R = 128
    BLOCK_C = 128

    eye_blocks = triton.cdiv(C, BLOCK_C)
    _eye_init_kernel[(batch, eye_blocks)](V, C, C * C, BLOCK=BLOCK_C)

    # Pad to an even field so the circle method yields disjoint pairs.
    n_even = C if C % 2 == 0 else C + 1
    ring = n_even - 1
    n_pairs = n_even // 2

    for _sweep in range(_BLOCKED_NUM_SWEEPS):
        for round_idx in range(ring):
            _jacobi_round_kernel[(batch, n_pairs)](
                W,
                V,
                R,
                C,
                R * C,
                C * C,
                round_idx,
                ring,
                BLOCK_R=BLOCK_R,
                BLOCK_C=BLOCK_C,
            )

    S = torch.empty(batch, C, dtype=torch.float32, device=device)
    _column_norm_kernel[(batch, C)](W, S, R, C, R * C, BLOCK_R=BLOCK_R)

    # pinv = V @ diag(1/sigma_filt) @ U^T with U[:, j] = W[:, j] / sigma_j, i.e.
    # pinv[i, l] = sum_j V[i, j] * W[l, j] / sigma_j^2. The contraction runs on
    # the native matmul: the Triton version crashed the XPU compiler with
    # "LLVM ERROR: Unsupported element type" on tl.trans + tl.dot tiles.
    thr = flag_gems.maximum(
        torch.full_like(S[:, :1], atol_val), S.amax(dim=-1, keepdim=True) * rtol_val
    )
    inv_sq = torch.where(S > thr, 1.0 / (S * S + 1e-38), torch.zeros_like(S))
    return torch.matmul(V * inv_sq[:, None, :], W.transpose(-2, -1))


def linalg_pinv(
    A: torch.Tensor,
    *,
    atol: float = None,
    rtol: float = None,
    hermitian: bool = False,
) -> torch.Tensor:
    """Compute the Moore-Penrose pseudoinverse using one-sided Jacobi SVD.

    Args:
        A: Input tensor of shape (*, m, n).
        atol: Absolute tolerance for singular value thresholding.
        rtol: Relative tolerance (default: max(m,n) * eps, or 0 when atol > 0).
        hermitian: Ignored; the SVD path yields the same pseudoinverse for
            hermitian input, it just does not exploit the structure.

    Returns:
        Pseudoinverse of shape (*, n, m).
    """
    logger.debug("GEMS LINALG_PINV")

    assert A.dtype in (
        torch.float32,
        torch.float64,
    ), f"linalg_pinv: expected float32 or float64, got {A.dtype}"

    if not A.is_contiguous():
        A = A.contiguous()

    orig_shape = A.shape
    m = orig_shape[-2]
    n = orig_shape[-1]
    k = min(m, n)

    # Flatten batch dimensions
    if A.dim() == 2:
        A_work = A.unsqueeze(0)
    else:
        A_work = A
    batch_shape = A_work.shape[:-2]
    batch = 1
    for d in batch_shape:
        batch *= d
    A_flat = A_work.reshape(batch, m, n)

    # Threshold follows torch semantics: cutoff = max(atol, rtol * sigma_max),
    # and rtol falls back to 0 when only a positive atol is given.
    atol_val = 0.0 if atol is None else float(atol)
    if rtol is None:
        eps = torch.finfo(A.dtype).eps
        rtol_val = 0.0 if atol_val > 0.0 else float(max(m, n)) * eps
    else:
        rtol_val = float(rtol)

    compute_dtype = A.dtype

    if compute_dtype == torch.float32 and m == n and n in _FAST_SQUARE_DIMS:
        # Single-launch pair-vectorized path for the small square shapes.
        # A_flat is a contiguous view (contiguity was forced above).
        out_f32 = _fast_square_pinv(A_flat, batch, n, atol_val, rtol_val)
    elif _REG_MAX_C > 0 and m == n and m <= _REG_MAX_C:
        # Single-launch register-resident path (small square matrices). Only
        # square inputs: with R != C the backend miscompiles the sweep loop
        # (mixed 4- and 8-lane vectors), so rectangular matrices stay on the
        # blocked path.
        out_f32 = _reg_pinv(A_flat.to(torch.float32), batch, m, n, atol_val, rtol_val)
    elif m > _FUSED_MAX_DIM or n > _FUSED_MAX_DIM:
        # Blocked path. One-sided Jacobi orthogonalizes columns, so it wants at
        # least as many rows as columns; for wide inputs use
        # pinv(A) = pinv(A^T)^T to get there.
        if m < n:
            W = A_flat.transpose(-2, -1).contiguous().to(torch.float32)
            R, C = n, m
            transposed = True
        else:
            # .to() is a no-op for float32 input, so clone to keep the caller's
            # tensor safe from the in-place rotations.
            W = A_flat.to(torch.float32).clone()
            R, C = m, n
            transposed = False

        out_f32 = _blocked_pinv(W, batch, R, C, atol_val, rtol_val)
        if transposed:
            out_f32 = out_f32.transpose(-2, -1).contiguous()
    else:
        # Determine block sizes (must be powers of 2 >= dimension)
        BLOCK_M = triton.next_power_of_2(m)
        BLOCK_N = triton.next_power_of_2(n)
        BLOCK_K = triton.next_power_of_2(k)

        # Number of Jacobi sweeps - balance convergence vs compile time
        # O(n^2/2 * sweeps) loop iterations are statically unrolled
        if k <= 4:
            NUM_SWEEPS = 10
        elif k <= 8:
            NUM_SWEEPS = 8
        else:
            NUM_SWEEPS = 5

        # Compute in float32 for the kernel
        A_f32 = A_flat.float() if A.dtype != torch.float32 else A_flat

        out_f32 = torch.empty(batch, n, m, dtype=torch.float32, device=A.device)

        grid = (batch,)
        _jacobi_pinv_kernel[grid](
            A_f32,
            out_f32,
            m,
            n,
            k,
            m * n,  # a_batch_stride
            n * m,  # out_batch_stride
            atol_val,
            rtol_val,
            NUM_SWEEPS=NUM_SWEEPS,
            BLOCK_M=BLOCK_M,
            BLOCK_N=BLOCK_N,
            BLOCK_K=BLOCK_K,
        )

    if compute_dtype != torch.float32:
        out = out_f32.to(compute_dtype)
    else:
        out = out_f32

    # Reshape to original batch shape + (n, m)
    out_shape = list(orig_shape[:-2]) + [n, m]
    return out.reshape(out_shape)


def _patch_generic_wrapper():
    """Route direct calls to the generic module's ``linalg_pinv`` to this override.

    ``SpecOpRegistrar`` rebinds ``flag_gems.linalg_pinv`` (the ATen dispatch
    entry and the package-level export) to this backend implementation, but a
    ``from flag_gems.ops.linalg_pinv import linalg_pinv`` binding resolves
    through the generic module, which the registrar does not touch. The
    benchmark harness imports the op exactly that way, so rebind the generic
    module's attribute too (same pattern as the kunlunxin ``rnn_relu``
    override). ``flag_gems.ops`` is imported before the backend ops module
    whenever ``import flag_gems`` runs, so the module is normally present; if
    it is not (standalone import of this file), skip silently.
    """
    import sys

    try:
        generic_module = sys.modules.get("flag_gems.ops.linalg_pinv")
        if generic_module is not None:
            generic_module.linalg_pinv = linalg_pinv
    except Exception:
        logger.debug("linalg_pinv generic-module rebind skipped", exc_info=True)


_patch_generic_wrapper()
